// Built once per cold start: lowercase species name -> array of its spawn records.
const SPAWN_INDEX = new Map();
for (const record of SPAWN_DATA) {
  const key = record.n.toLowerCase();
  if (!SPAWN_INDEX.has(key)) SPAWN_INDEX.set(key, []);
  SPAWN_INDEX.get(key).push(record);
}

const MAX_SPECIES_PER_REQUEST = 12; // guards against a pathological message matching huge swaths of the index

/**
 * Finds every species name from SPAWN_INDEX that appears (as a whole word) in the player's
 * message, and returns their spawn records. Whole-word matching avoids short names like "Ho"
 * or "Mime" false-matching inside unrelated words.
 */
function findRelevantSpawns(message) {
  const lower = message.toLowerCase();
  const matches = [];
  for (const [name, records] of SPAWN_INDEX) {
    if (matches.length >= MAX_SPECIES_PER_REQUEST) break;
    const re = new RegExp(`\\b${name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`);
    if (re.test(lower)) matches.push(...records);
  }
  return matches;
}

function formatSpawnLore(records) {
  if (records.length === 0) return '';
  const lines = records.map(r => {
    const bits = [];
    bits.push(`${r.n} — ${r.b || 'unknown rarity'}, Lv ${r.lo}-${r.hi}`);
    bits.push(`biomes: ${r.bio || 'any'}`);
    if (r.t && r.t !== 'any') bits.push(`time: ${r.t}`);
    if (r.w && r.w !== 'any') bits.push(`weather: ${r.w}`);
    if (r.c) bits.push(`requires: ${r.c}`);
    if (r.ac) bits.push(`excludes: ${r.ac}`);
    return `- ${bits.join(' | ')}`;
  });
  return `Verified spawn data for the Pokémon mentioned:\n${lines.join('\n')}`;
}

function buildSystemPrompt(userMessage) {
  const spawnLore = formatSpawnLore(findRelevantSpawns(userMessage));
  return spawnLore ? `${BASE_SYSTEM_PROMPT}\n\n${spawnLore}` : BASE_SYSTEM_PROMPT;
}

// ---------- Helpers ----------

function corsHeaders(origin) {
  const allowOrigin = ALLOWED_ORIGINS.includes(origin) ? origin : ALLOWED_ORIGINS[0];
  return {
    'Access-Control-Allow-Origin': allowOrigin,
    'Access-Control-Allow-Methods': 'POST, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, X-Device-Fingerprint',
    'Vary': 'Origin',
  };
}

function jsonResponse(body, status, origin, extraHeaders = {}) {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      'Content-Type': 'application/json',
      ...corsHeaders(origin),
      ...extraHeaders,
    },
  });
}

// A raw X-Device-Fingerprint header is untrusted client input that ends up inside a KV key —
// reject anything that isn't a short, plain visitorId-shaped token before it's ever used.
// FingerprintJS v4 visitorIds are 32-char hex, but this stays a little more permissive in
// case the CDN library's output format changes.
function sanitizeFingerprint(raw) {
  if (typeof raw !== 'string') return null;
  const trimmed = raw.trim();
  if (!trimmed || trimmed.length > 128) return null;
  if (!/^[a-zA-Z0-9_-]+$/.test(trimmed)) return null;
  return trimmed;
}

/**
 * KV has no atomic "increment but keep original TTL" operation, so the counter's own
 * expiry timestamp is stored alongside the count and reapplied as a shrinking TTL on every
 * write. That's what makes this "N requests within 24 hours of the FIRST request" rather
 * than "24 hours from whatever request happened most recently" (which is what you'd get if
 * you just called `put` with a fresh expirationTtl every time).
 */
async function getRateLimitRecord(env, key) {
  const now = Date.now();
  const raw = await env.RATE_LIMITER.get(key);
  const record = raw ? JSON.parse(raw) : null;
  if (!record || record.resetAt <= now) {
    return { count: 0, resetAt: now + RATE_LIMIT_WINDOW_SECONDS * 1000 };
  }
  return record;
}

async function putRateLimitRecord(env, key, record) {
  const ttlSeconds = Math.max(60, Math.ceil((record.resetAt - Date.now()) / 1000)); // KV minimum TTL is 60s
  await env.RATE_LIMITER.put(key, JSON.stringify(record), { expirationTtl: ttlSeconds });
}

/**
 * Checks both the IP bucket and, if the client sent a valid device fingerprint, the
 * fingerprint bucket — and rejects if EITHER has hit DAILY_LIMIT. This is what stops someone
 * from resetting their quota by switching VPN exit IPs while keeping the same browser/device.
 * Buckets are only incremented together, after confirming neither is already maxed out, so a
 * rejected request never partially consumes one bucket without the other.
 */
async function checkAndIncrementRateLimit(env, ip, fingerprint) {
  const ipKey = `ratelimit:ip:${ip}`;
  const fpKey = fingerprint ? `ratelimit:fp:${fingerprint}` : null;

  const ipRecord = await getRateLimitRecord(env, ipKey);
  const fpRecord = fpKey ? await getRateLimitRecord(env, fpKey) : null;

  const ipBlocked = ipRecord.count >= DAILY_LIMIT;
  const fpBlocked = !!fpRecord && fpRecord.count >= DAILY_LIMIT;

  if (ipBlocked || fpBlocked) {
    const blockingResetAt = Math.max(
      ipBlocked ? ipRecord.resetAt : 0,
      fpBlocked ? fpRecord.resetAt : 0
    );
    return { allowed: false, retryAfterSeconds: Math.ceil((blockingResetAt - Date.now()) / 1000) };
  }

  ipRecord.count += 1;
  await putRateLimitRecord(env, ipKey, ipRecord);

  if (fpKey) {
    fpRecord.count += 1;
    await putRateLimitRecord(env, fpKey, fpRecord);
  }

  return { allowed: true, remaining: DAILY_LIMIT - ipRecord.count };
}

async function callGemini(env, userMessage) {
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${GEMINI_MODEL}:generateContent?key=${env.GEMINI_API_KEY}`;

  const payload = {
    systemInstruction: {
      parts: [{ text: buildSystemPrompt(userMessage) }],
    },
    contents: [
      { role: 'user', parts: [{ text: userMessage }] },
    ],
    generationConfig: {
      temperature: 0.7,
      maxOutputTokens: 300, // keeps replies short — cheaper and stays within a free-tier quota faster
    },
  };

  const res = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });

  if (!res.ok) {
    const errText = await res.text().catch(() => '');
    throw new Error(`Gemini API error ${res.status}: ${errText}`);
  }

  const data = await res.json();
  const text = data?.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!text) throw new Error('Gemini returned no usable text.');
  return text;
}

// ---------- Entry point ----------

export default {
  async fetch(request, env) {
    const origin = request.headers.get('Origin') || '';

    if (request.method === 'OPTIONS') {
      return new Response(null, { status: 204, headers: corsHeaders(origin) });
    }

    if (request.method !== 'POST') {
      return jsonResponse({ error: 'Method not allowed' }, 405, origin);
    }

    let body;
    try {
      body = await request.json();
    } catch {
      return jsonResponse({ error: 'Invalid JSON body' }, 400, origin);
    }

    const message = typeof body?.message === 'string' ? body.message.trim() : '';
    if (!message) {
      return jsonResponse({ error: 'Message is required' }, 400, origin);
    }
    if (message.length > MAX_MESSAGE_LENGTH) {
      return jsonResponse({ error: `Message too long (max ${MAX_MESSAGE_LENGTH} characters)` }, 400, origin);
    }

    const ip = request.headers.get('CF-Connecting-IP') || 'unknown';
    const fingerprint = sanitizeFingerprint(request.headers.get('X-Device-Fingerprint'));

    // Gate + increment BEFORE calling Gemini, per spec — note this means a failed upstream
    // call still consumes one of the user's slots for the day. If you'd rather only charge
    // quota on a successful reply, move the increment to after a successful callGemini().
    const rateLimit = await checkAndIncrementRateLimit(env, ip, fingerprint);
    if (!rateLimit.allowed) {
      return jsonResponse(
        { error: 'Daily limit reached. Try again tomorrow!' },
        429,
        origin,
        { 'Retry-After': String(rateLimit.retryAfterSeconds) }
      );
    }

    try {
      const reply = await callGemini(env, message);
      return jsonResponse({ reply }, 200, origin);
    } catch (err) {
      return jsonResponse({ error: 'LumyBot is temporarily unavailable. Please try again shortly.' }, 502, origin);
    }
  },
};
